def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_without_build = v[:v.index('+')]
        else:
            v_without_build = v

        # Split into core version and pre-release
        if '-' in v_without_build:
            core_part, prerelease_part = v_without_build.split('-', 1)
        else:
            core_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_ids = prerelease_part.split('.')
            # Convert to sortable form: (is_numeric, numeric_value or string)
            parsed_ids = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    parsed_ids.append((0, int(identifier)))
                else:
                    parsed_ids.append((1, identifier))
        else:
            parsed_ids = None

        return (major, minor, patch, parsed_ids)

    def sort_key(v):
        major, minor, patch, parsed_ids = parse_version(v)

        # Create sort key
        # Versions without pre-release sort after versions with pre-release
        # So: version with pre-release should come first (lower in sort)
        # We use (major, minor, patch, has_prerelease, prerelease_ids)
        # has_prerelease: 0 if has pre-release (comes first), 1 if no pre-release

        if parsed_ids is None:
            # No pre-release: sorts after same version with pre-release
            return (major, minor, patch, 1, [])
        else:
            # Has pre-release: sorts before same version without
            return (major, minor, patch, 0, parsed_ids)

    # Use stable sort to preserve input order for equal precedence
    sorted_versions = sorted(enumerate(versions), key=lambda x: sort_key(x[1]))
    return [v for idx, v in sorted_versions]

